Trigger.TriggerText:
IF :POLICY_HDR.START_DATE < TRUNC(SYSDATE) THEN
  MESSAGE('Cover cannot start in the past');
  RAISE FORM_TRIGGER_FAILURE;
END IF;
:POLICY_HDR.END_DATE := ADD_MONTHS(:POLICY_HDR.START_DATE, 12) - 1;

:POLICY_HDR.PREMIUM := pkg_rating.calc_premium(:VEHICLE.VEHICLE_VALUE, :INSURED.DOB, :INSURED.NCD_YEARS);
IF pkg_underwriting.needs_referral(:VEHICLE.VEHICLE_VALUE, :INSURED.LICENCE_YEARS) THEN
  :POLICY_HDR.STATUS := 'REFERRED';
  MESSAGE('Referred to underwriter');
ELSE
  :POLICY_HDR.STATUS := 'ISSUED';
END IF;
COMMIT_FORM;

IF MONTHS_BETWEEN(:POLICY_HDR.START_DATE, :INSURED.DOB) / 12 < 18 THEN
  MESSAGE('Policy holder must be at least 18 on the start date');
  RAISE FORM_TRIGGER_FAILURE;
END IF;
